import io.github.diodeme.ji.agent.*;
import io.github.diodeme.ji.ai.*;
import io.github.diodeme.ji.host.*;
import io.github.diodeme.ji.testkit.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
String hashOf(String value) { try { return java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8))); } catch(Exception e) { throw new RuntimeException(e); } }
var rejecting = Executors.newSingleThreadExecutor(); rejecting.shutdown();
var store3 = new MemoryHostStore();
var runtime3 = new AgentRuntimeBuilder().provider(new ScriptedModelProvider()).sessionStore(store3).permissionDecider(new PermissionBroker(Clock.systemUTC())).executor(rejecting).build();
var sessions3 = new SessionApplicationService(runtime3);
var sid3 = sessions3.create(new ModelRef("faux", "faux-1"), ".").id();
var prompts3 = new PromptApplicationService(sessions3, store3);
try { prompts3.prompt(sid3, "start-failure-command", "hello"); System.out.println("START_FAILURE=ACCEPTED"); } catch(Throwable t) { System.out.println("START_FAILURE=" + t.getClass().getSimpleName()); }
System.out.println("START_FAILURE_JOURNAL_PRESENT=" + store3.command(sid3, "start-failure-command", hashOf("hello")).isPresent());
System.out.println("START_FAILURE_ACTIVE=" + sessions3.hasActiveRun(sid3));
try { prompts3.prompt(sid3, "start-failure-command", "hello"); System.out.println("START_RETRY=ACCEPTED"); } catch(Throwable t) { System.out.println("START_RETRY=" + t.getClass().getSimpleName() + ":" + t.getMessage()); }
runtime3.close();
var gate4 = new ScriptedModelProvider.Gate();
var provider4 = new ScriptedModelProvider().enqueue(List.of(new ScriptedModelProvider.Step.Wait(gate4), new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
var store4 = new MemoryHostStore();
var runtime4 = new AgentRuntimeBuilder().provider(provider4).sessionStore(store4).permissionDecider(new PermissionBroker(Clock.systemUTC())).build();
var sessions4 = new SessionApplicationService(runtime4);
var sid4 = sessions4.create(new ModelRef("faux", "faux-1"), ".").id();
var prompts4 = new PromptApplicationService(sessions4, store4);
var first4 = prompts4.prompt(sid4, "inflight-command", "hello");
try { prompts4.prompt(sid4, "inflight-command", "hello"); System.out.println("INFLIGHT_RETRY=ACCEPTED"); } catch(Throwable t) { System.out.println("INFLIGHT_RETRY=" + t.getClass().getSimpleName() + ":" + t.getMessage()); }
first4.run().orElseThrow().abort(); gate4.open(); first4.run().orElseThrow().completion().toCompletableFuture().get(2, TimeUnit.SECONDS);
runtime4.close();
/exit
